import { BrowserRouter as Router, Routes, Route, Link } from "react-router-dom";
import "./App.css";
import Menu2 from "./components/Menu2";
import Form from "./components/Form";
import Navbar from "./components/Navbar";
import Table from "./components/Table";
import History from "./components/History";
import FinalArea from "./components/FinalArea";
function App() {
  return (
    <div className="bg-gray-50 min-h-screen">
      <Navbar />
      <Routes>
          <Route path="/" element={<Form />} />
          <Route path="/table" element={<Table />} />
          <Route path="/final-area" element={<FinalArea />} />
          <Route path="/rss" element={<Menu2 Name="RSS" />} />
          <Route path="/top" element={<Menu2 Name="TOP" />} />
          <Route path="/pnr-overhead-summary" element={<Menu2 Name="Pnr Overhead Summary" />} />
          <Route path="/history" element={<History />} />
        </Routes>
      <Form/>
      <Table />
      <FinalArea/>
      {/* Menu Section with Full-Width Buttons */}
      <div className="w-full bg-gray-100 mt-8">
        <div className="w-full bg-white shadow-md rounded-lg p-6 border">
          <div className="flex justify-around w-full gap-4">
            {/* <Menu2 Name="RSS"/>
            <Menu2 Name="TOP" />
            <Menu2 Name="Pnr Overhead Summary" />
            <History/> */}
            <Link to="/rss" className="text-blue-500 hover:underline">RSS</Link>
              <Link to="/top" className="text-blue-500 hover:underline">TOP</Link>
              <Link to="/pnr-overhead-summary" className="text-blue-500 hover:underline">Pnr Overhead Summary</Link>
              <Link to="/history" className="text-blue-500 hover:underline">History</Link>
          </div>
        </div>
      </div>

    </div>
  );
}

export default App;
